(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.28)*16+Math.sin(x*0.016+t*0.33)*11;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8;
  const w2y = Math.cos((x-y)*0.012-t*0.18)*9;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.9],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1.1],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.8],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 1.2],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.7],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.0],
    [80+Math.sin(t*0.45+3)*110, 140+Math.cos(t*0.65+2)*70, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+1)*70, 100+Math.sin(t*0.75+4)*90, 0.075, 1.8, 1.15]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    hS += Math.sin(d*f*1.4-t*sp*0.4+2.8)*w*0.4;
  }
  const act=aS/7.5, inh=iS/7.5, har=hS/7.5;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07+t*1.8)*Math.sin(sy*0.065-t*1.4)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*6+t*0.9)*0.15;
  const grain = Math.sin(sx*0.8)*Math.sin(sy*0.7)*Math.sin((sx+sy)*0.5+t*3)*0.06;
  const reaction = Math.tanh((act-inh*0.65+bg*0.3+spiral+har*0.25+grain)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const micro = Math.sin(sx*0.3+sy*0.2+t*4)*Math.sin(sx*0.2-sy*0.3-t*3)*0.08;
  const blend = reaction*0.7+cell*0.2+micro*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[10,45,88],[12,85,115],[18,135,130],[60,170,120],
    [160,195,80],[220,185,60],[230,140,55],[210,95,65],[170,50,60],
    [110,25,55],[55,15,48],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,reaction-0.3)*0.3;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*50)|0)
  ];
}
